<?php

namespace App\Models\Concerns;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Str;

/**
 * Every business table carries two identifiers: a BIGINT UNSIGNED primary key
 * that every foreign key points at, and a ULID column that is safe to expose
 * in URLs and API payloads.
 *
 * The primary key is generated by MySQL, but the ULID column is NOT NULL with
 * no default, so it has to be filled before the insert.
 */
trait HasPublicId
{
    protected static function bootHasPublicId(): void
    {
        static::creating(function (Model $model): void {
            if (blank($model->getAttribute('ulid'))) {
                $model->setAttribute('ulid', (string) Str::ulid());
            }
        });
    }

    /**
     * Route model binding resolves the public identifier, never the internal
     * sequential key.
     */
    public function getRouteKeyName(): string
    {
        return 'ulid';
    }
}
